def pre(enrich):
    a=enrich.P["apple-icloud"]
    a["facts"]=a["facts"]+["Access lasts 3 years from the first approved request, then the legacy account is permanently deleted","On approval, the original Apple Account stops working and Activation Lock is removed from its devices"]
    a.setdefault("extra",[]); a["extra"]=[("How long does a Legacy Contact have access?","Three years from when the first legacy account request is approved. After that, Apple permanently deletes the legacy account, so download anything you want to keep."),("Does Legacy Contact remove Activation Lock?","Yes. Apple says Activation Lock is removed from devices that use the original Apple Account once access is approved. The devices then need to be erased and restored before reuse.")]+a["extra"]
    if APPLE not in a.get("sources",[]): a["sources"]=a.get("sources",[])+[APPLE]
    if APPLE_D not in a["sources"]: a["sources"].append(APPLE_D)
    g=enrich.P["google-gmail"]
    g["facts"]=g["facts"]+["Inactive Account Manager waits between 3 and 18 months of inactivity (Google)","The 2-year inactive-account policy applies regardless of your Inactive Account Manager settings"]
    g.setdefault("extra",[]); g["extra"]=[("How long does Inactive Account Manager wait?","You choose the period. Google says it can act after 3 to 18 months of inactivity. Google's separate 2-year inactivity policy still applies.")]+g["extra"]
    g["sources"]=g.get("sources",[])+[GBLOG]
    enrich.GUIDE_NEW.append(EXEC)
    for i,x in enumerate(enrich.GUIDE_NEW):
        if x[0]=="australian-digital-estate-guide":
            s,t,an,st,f,src,tl,rel=x
            enrich.GUIDE_NEW[i]=(s,t,an,st,f+[("Is probate the same in every Australian state?","No. Each state and territory's Supreme Court runs its own probate registry with its own forms, notice rules and fees. See the state-by-state table on this page."),("Is there one place to notify organisations of a death in Australia?","Yes. The Australian Death Notification Service (deathnotification.gov.au) is a free government service that lets you notify several participating organisations at once.")],src+[(n,u) for _,n,u,_ in STATES]+[("Australian Death Notification Service","https://deathnotification.gov.au/")],tl,rel)
STATES=[("NSW","Supreme Court of NSW: Applying for a grant of probate","https://supremecourt.nsw.gov.au/wills-probate/applications/applying-for-probate.html","Most uncontested probate applications are filed online through the NSW Online Registry."),
("VIC","Supreme Court of Victoria: How to apply for a grant of probate or administration","https://www.supremecourt.vic.gov.au/wills-and-probate/how-to-apply-for-a-grant-of-probate-or-administration","Applications are made online through RedCrest-Probate after advertising your intention to apply."),
("QLD","Queensland Courts: Apply for a grant of administration","https://www.courts.qld.gov.au/services-and-online-actions/applications-and-appeals/wills-and-probate/apply-for-a-grant-of-administration","File with a Supreme Court Registry after publishing a notice of intention to apply."),
("WA","Supreme Court of WA: Before applying (probate)","https://supremecourt.wa.gov.au/B/before_applying.aspx","Applications go to the Supreme Court Probate Office; an online application tool helps you prepare the forms."),
("SA","Courts Administration Authority SA: Probate","https://www.courts.sa.gov.au/going-to-court/probate/","All probate lodgements must be made electronically through CourtSA."),
("TAS","Supreme Court of Tasmania: Probate","https://www.supremecourt.tas.gov.au/probate/","The Probate Registry handles all applications for grants of probate and administration in Tasmania."),
("ACT","ACT Supreme Court: Wills and probate","https://courts.act.gov.au/supreme/law-and-practice/wills-and-probate","You must publish a notice of intention to apply before filing."),
("NT","Supreme Court NT: Wills & probate","https://supremecourt.nt.gov.au/about/registry/wills-and-probate","File a notice of intended application with the Probate Registry first; it's published before you apply.")]
AU_HTML="<h2 id='states'>How does probate work in each state and territory?</h2><p>Every state and territory's Supreme Court runs its own probate registry. Start with the official page for the state where the person lived or held assets.</p><div class='ctw'><table class='ct'><caption>Probate basics by state (official court pages)</caption><thead><tr><th scope='col' class='corner'>State</th><th scope='col'>Probate basics</th><th scope='col'>Official page</th></tr></thead><tbody>"+"".join(f"<tr><th scope='row'>{s}</th><td>{E(b)}</td><td><a href='{u}' rel='noopener' target='_blank'>{E(n.split(':')[0])} ↗</a></td></tr>" for s,n,u,b in STATES)+"</tbody></table></div><p>To tell several organisations about a death at once, use the free <a href='https://deathnotification.gov.au/' rel='noopener' target='_blank'>Australian Death Notification Service ↗</a>.</p>"
PDF="/assets/afterkeep-executor-first-30-days-checklist.pdf"
EXEC_STEPS=[
("Days 1–3","Get several certified copies of the death certificate (or the interim document your state provides)."),
("Days 1–3","Secure their phone, laptop and tablets. Keep them charged; don't factory-reset anything yet."),
("Days 1–3","Look for a plan: password manager emergency access, an Apple Legacy Contact access key, a Google Inactive Account Manager email, and a list of accounts."),
("Days 1–7","Find the will and confirm who the executor is. If there's no will, find out who can apply to be administrator."),
("Days 1–7","Don't log in with their password unless a lawyer says it's OK; many platform terms forbid it."),
("Week 1","List every account you can find: email, cloud storage, socials, banks, PayPal, crypto, domains and subscriptions."),
("Week 1","Download or preserve irreplaceable photos and files first, through official legacy tools or deceased-user requests."),
("Week 2","Use each platform's official deceased-user process. Request data before asking for closure."),
("Week 2","In Australia, use the free Australian Death Notification Service to notify participating organisations."),
("Weeks 2–4","Cancel or pause paid subscriptions to stop charges."),
("Weeks 2–4","Memorialise or close social media accounts (Facebook, Instagram, LinkedIn, X) according to the family's wishes."),
("Weeks 2–4","Check whether asset holders need probate or letters of administration, and start the application with your state's Supreme Court if they do."),
("Day 30","Record what's done, what's pending and every reference number. Keep copies of everything you sent.")]
EXEC=("what-to-do-when-someone-dies-digital-checklist","What to do when someone dies: the executor's digital checklist (first 30 days)",
 "In the first 30 days, an executor should secure the person's devices, find any legacy plan they left, list their accounts, save irreplaceable photos and files, and then use each platform's official deceased-user process. Request data before closing accounts, and check whether probate is needed. A printable PDF version is below.",
 [f"{d}: {s}" for d,s in EXEC_STEPS],
 [("What should an executor do first with digital accounts?","Secure the devices, get certified death certificates, and look for a legacy plan such as password manager emergency access or an Apple Legacy Contact key. Don't reset devices or close accounts yet."),
  ("Should I close accounts straight away?","No. Request data first. Closing an account can stop you getting its content later."),
  ("Can I log in with their password?","Many platform terms prohibit it and laws vary. Ask the executor's lawyer before using someone else's credentials."),
  ("Do I need probate for online accounts?","It depends on the asset holder. Many banks and platforms ask for a grant of probate or letters of administration before releasing money or data."),
  ("Is there a printable version?","Yes. Download the free PDF checklist from this page.")],
 [("Australian Death Notification Service","https://deathnotification.gov.au/"),APPLE_D,("Google: Submit a request regarding a deceased user's account","https://support.google.com/accounts/troubleshooter/6357590"),("ATO: Checklist: what to do when someone dies","https://www.ato.gov.au/individuals-and-families/deceased-estates/checklist-what-to-do-when-someone-dies")],
 ["13 steps over 30 days","Free printable PDF","Request data before closing accounts"],
 ["/guides/access-deceased-persons-phone-and-accounts/","/guides/australian-digital-estate-guide/","/guides/digital-estate-checklist/"])
PDFBTN=f"<p><a class='btn' href='{PDF}' download>Download the printable PDF checklist</a></p>"
EXTRA={"australian-digital-estate-guide":AU_HTML,EXEC[0]:PDFBTN,"digital-estate-checklist":f"<p><a href='{PDF}' download>Printable executor's 30-day checklist (PDF)</a></p>"}
STEAM=("Steam Subscriber Agreement","https://store.steampowered.com/subscriber_agreement/")
GAMES=dict(slug="game-libraries",name="game libraries (Steam, GOG, Epic, PlayStation, Xbox)",cat="platforms",url=STEAM[1],
 answer="In most cases your digital games can't be passed on. Steam, Epic, PlayStation and Xbox license games to you personally and say the licence isn't transferable. Family can usually only stop charges or close the account. Write down what you own, and keep saves or mods backed up separately.",
 steps=["Write down which stores you use (Steam, GOG, Epic, PlayStation, Xbox) and the email on each account.","Store logins in a password manager with emergency access so someone can cancel subscriptions and close accounts.","Back up local saves, screenshots and mods you care about outside the store.","After a death: cancel subscriptions such as Game Pass or PlayStation Plus through the account or the payment card.","Contact each store's support with a death certificate to ask about closure. Don't expect the games library to be transferred."],
 faqs=[("Can I leave my Steam library to someone?","Steam's Subscriber Agreement says subscriptions are licences, Valve doesn't recognise transfers outside Steam (including by operation of law), and subscriptions aren't transferable."),
       ("What about Epic Games?","Epic's terms say your licence is personal and non-transferable, and you can't sell, give away or trade your Epic Games Account."),
       ("What about PlayStation?","PlayStation's Australian terms say your licence to use Digital Products is not transferable unless local law says it must be."),
       ("What about Xbox?","The Microsoft Services Agreement gives you a personal, non-transferable licence to Xbox game currency and virtual goods. Microsoft accounts are closed automatically after two years of inactivity if no one can sign in."),
       ("What about GOG?","We couldn't verify a published GOG bereavement policy from an official source. Contact GOG Support with a death certificate.")],
 facts=["Steam: licences, not transferable (Subscriber Agreement)","Epic: personal, non-transferable licence; account can't be given away","PlayStation (AU): licence not transferable unless local law requires","Xbox: personal, non-transferable licence to currency and virtual goods","GOG: no official bereavement policy we could verify"],
 sources=[STEAM,("Epic Games Terms of Service","https://legal.epicgames.com/epicgames/tos"),("PlayStation Terms of Service (Australia)","https://www.playstation.com/en-au/legal/psn-terms-of-service/"),("Microsoft Services Agreement","https://www.microsoft.com/en-au/servicesagreement"),("Microsoft: Accessing Outlook.com, OneDrive and other services when someone has died","https://support.microsoft.com/en-us/account-billing/accessing-outlook-com-onedrive-and-other-microsoft-services-when-someone-has-died-ebbd2860-917e-4b39-9913-212362da6b2f")],
 lost=["Purchased game libraries (licences end with the account)","Wallet balances and in-game currency","Cloud saves if the account is closed"],
 related=["/platforms/microsoft-outlook/","/guides/digital-estate-checklist/"])
def T(slug,name,cat,url,verdict,pricing,best,pros,cons,sources): return dict(slug=slug,name=name,cat=cat,url=url,verdict=verdict,pricing=pricing,best=best,pros=pros,cons=cons,sources=sources)
BK1="https://support.bitkey.world/hc/en-us/articles/32141067207444-What-is-Inheritance-and-how-does-it-work"
NEWT=[
T("bitkey","Bitkey","crypto",BK1,"A bitcoin-only 2-of-3 multisig wallet with built-in inheritance: your beneficiary starts a claim, and funds unlock only after a 6-month delay you can cancel.","Hardware listed at $250 on bitkey.world. Check current pricing.","Bitcoin holders who want simple self-custody with inheritance built in.",["Built-in inheritance with a 6-month security delay","You get alerts and can cancel a claim","No seed phrase; 2-of-3 multisig"],["Bitcoin only","Beneficiary needs their own Bitkey device","Bitkey says a beneficiary isn't automatically the legal owner; your will may take precedence"],[("Bitkey Support: What is Inheritance and how does it work?",BK1),("Bitkey: Home","https://bitkey.world/")]),
T("nunchuk","Nunchuk","crypto","https://nunchuk.io/inheritance","A non-custodial bitcoin inheritance platform: Nunchuk holds one key it can't use alone, and a timelock unlocks funds for your beneficiary on the date you set.","Free DIY wallets; the inheritance plan (Honey Badger) is listed at 480/year. Check current pricing and currency.","Bitcoin holders who want timelock-based inheritance without KYC.",["On-chain or off-chain timelock","Beneficiary can claim without Nunchuk's involvement","No KYC required"],["Inheritance needs a paid plan","Bitcoin only","Setup is more technical than a custodial service"],[("Nunchuk: Inheritance","https://nunchuk.io/inheritance"),("Nunchuk: Pricing","https://nunchuk.io/pricing")]),
T("liana","Liana","crypto","https://wizardsardine.com/liana/wallet","A free, open-source bitcoin wallet from Wizardsardine with time-based recovery paths, so a family member or trusted contact can access funds if something happens to you.","Liana Wallet is free and open source; Liana Business is a paid service.","Technical bitcoin holders who want DIY inheritance with no company holding keys.",["Free and open source","Time-based recovery path for heirs","No third party holds your keys"],["DIY setup with community support only (free edition)","Bitcoin only","Heirs must follow the recovery path themselves"],[("Liana: Home","https://wizardsardine.com/liana/"),("Liana Wallet","https://wizardsardine.com/liana/wallet")]),
T("anchorwatch","AnchorWatch","crypto","https://www.anchorwatch.com/inheritance","Bitcoin custody with an Inheritance Protocol and estate documentation for your attorney, plus optional Lloyd's of London insurance for US customers.","Check official pricing.","Larger bitcoin holders who want insured, documented inheritance.",["Documentation structured for trust and estate attorneys","Recovery whenever your beneficiary contacts them","Optional insurance (US customers)"],["Prices not published on the inheritance page","Bitcoin only","Relies on a company process"],[("AnchorWatch: Inheritance","https://www.anchorwatch.com/inheritance"),("AnchorWatch: Home","https://www.anchorwatch.com/")]),
T("trustworthy","Trustworthy","estate","https://www.trustworthy.com/","A family document organiser with an encrypted vault and legacy access options. It organises information; it doesn't say it writes wills.","Free plan; Silver $10, Gold $20, Platinum $40 a month, paid annually. Check current pricing.","Families who want one organised, shareable place for important documents.",["Free plan available","AES-256 encryption and multi-factor authentication","Shared access for family members"],["Doesn't state that it creates wills","Countries supported not stated","Advanced features need paid plans"],[("Trustworthy: Home","https://www.trustworthy.com/"),("Trustworthy: Pricing","https://www.trustworthy.com/pricing")]),
T("mywishes","MyWishes","estate","https://mywishes.co.uk/","A free UK-based platform to write a will, a 'Digital & Social Media Will', funeral wishes and an advance care plan, then download, print and share them.","Free.","People who want a free way to record digital and end-of-life wishes.",["Free to use","Covers wills, digital legacy, funeral wishes and care plans","Download, print and share your documents"],["UK-focused; check the will rules where you live","You must print and sign documents yourself","No built-in emergency access to accounts"],[("MyWishes: Home","https://mywishes.co.uk/")]),
T("securesafe","SecureSafe","estate","https://help.securesafe.com/securesafe-settings-data-inheritance","A Swiss-hosted vault whose data inheritance (activator code plus a blocking period) is only in SecureSafe Classic; SecureSafe says the new app doesn't have it.","Check official pricing.","Existing SecureSafe Classic users who already set up data inheritance.",["Assign specific passwords and files to each beneficiary","Blocking period lets you stop an accidental activation","Swiss-hosted"],["Data inheritance isn't available in the new app","Pricing not checked","Classic accounts may need moving to the new product"],[("SecureSafe Help: Data inheritance settings","https://help.securesafe.com/securesafe-settings-data-inheritance"),("SecureSafe Help: Activators and beneficiaries","https://help.securesafe.com/data-inheritance-activators-beneficiaries"),("SecureSafe Help: Old vs new version","https://help.securesafe.com/securesafe-file-old-vs-new-version")]),
T("life-ledger","Life Ledger","estate","https://www.lifeledger.com/","A free UK death notification service: notify over 1,000 UK companies of a death from one place and track progress online.","Free, with unlimited notifications.","Families handling a UK estate who want to notify many companies at once.",["Free","1,000+ UK companies","Invite family to help"],["UK only","Doesn't create wills","Used after a death, not for planning access"],[("Life Ledger: Home","https://www.lifeledger.com/")]),
T("settld","Settld","estate","https://settld.care/","A free UK bereavement admin service that reports a death to multiple companies in one go and tracks updates in one secure space.","Free to use.","Families handling a UK estate after a death.",["Free","Works with over 1,400 organisations","Complements the UK's Tell Us Once"],["UK only","Doesn't create wills","Used after a death, not for planning access"],[("Settld: Home","https://settld.care/")]),
]
