def cmp(CMP):
    for c in CMP:
        if c["slug"]=="google-inactive-account-manager-vs-apple-legacy-contact":
            c["faqs"]=[("How long does each one wait or last?","Google's Inactive Account Manager acts after an inactivity period you choose, between 3 and 18 months. Apple Legacy Contact access lasts 3 years from the first approved request, then the legacy account is deleted."),("Does Apple Legacy Contact remove Activation Lock?","Yes. Once access is approved, Apple removes Activation Lock from devices using the original Apple Account.")]+c["faqs"]
            c["sources"]=c["sources"]+[GBLOG,APPLE]
TRI_SLUG="bitwarden-vs-1password-vs-keeper-emergency-access"
TRI_TITLE="Bitwarden vs 1Password vs Keeper for emergency access"
TRI_ANS="Bitwarden and Keeper both have built-in emergency access; 1Password doesn't. Bitwarden lets trusted contacts request View or Takeover access after a wait time you set, with Premium listed at US$19.80 a year (checked 15 Oct 2026). Keeper allows up to 5 contacts with an optional delay of up to 3 months. 1Password relies on a printed Emergency Kit."
TRI_HEIRS=[("Bitwarden",["Your contact needs a free or paid Bitwarden account on the same server.","They request View or Takeover access from their account.","Access is granted when you approve it or when your wait time runs out."]),
("Keeper",["Your contact needs their own Keeper account.","After the access delay you set (optional, up to 3 months), they can log in to your vault.","Up to 5 contacts can be named."]),
("1Password",["There's no built-in emergency request.","Your heir uses the Emergency Kit you left (sign-in address, email, Secret Key and password).","On Families or business plans, an organiser can help recover a member's account."])]
TRI_FAQ=[("Which has the best emergency access: Bitwarden, 1Password or Keeper?","Bitwarden, for most people: built-in requests, View or Takeover access, and a wait time you control. Keeper is a strong alternative. 1Password has no built-in emergency access."),
("How much does Bitwarden Premium cost?","Bitwarden's pricing page lists Premium at US$19.80 a year (checked 15 Oct 2026)."),
("How many emergency contacts can I have?","Bitwarden: no limit stated. Keeper: up to 5. 1Password: anyone you give your Emergency Kit to."),
("Does Afterkeep store my passwords?","No. Afterkeep is a comparison and guide directory only.")]
SHORT=[("What happens to my Gmail when I die?","Google never shares your password. With Inactive Account Manager, up to 10 contacts get the data you chose after 3–18 months of inactivity; otherwise family can file a deceased-user request.","/platforms/google-gmail/"),
("Bitwarden vs 1Password emergency access?","Bitwarden has built-in emergency access (View or Takeover after a wait you set); 1Password has none and relies on the Emergency Kit.","/compare/bitwarden-vs-1password-emergency-access/"),
("Digital estate planning in Australia?","Make a will, list your digital assets, use a password manager with emergency access, and check your state Supreme Court's probate rules.","/guides/australian-digital-estate-guide/"),
("Best crypto inheritance tools?","Casa is our top pick; Bitkey, Nunchuk, Unchained, Vault12, Liana and AnchorWatch are good alternatives depending on custody needs.","/best/best-crypto-inheritance-tools/"),
("Best digital legacy vault?","It depends on whether you need legal documents (GoodTrust, Trust & Will) or an organiser (Everplans, Trustworthy); pair either with a password manager.","/best/best-digital-legacy-vaults/"),
("What happens to my iCloud when I die?","A Legacy Contact with your access key and death certificate gets 3 years of access; Activation Lock is removed. Keychain and purchases are excluded.","/platforms/apple-icloud/"),
("How do I access a deceased person's iPhone?","Apple can't remove a passcode without erasing the device; use a Legacy Contact key or Apple's deceased-account process.","/guides/access-deceased-persons-phone-and-accounts/"),
("Digital estate checklist?","Inventory accounts, set up emergency access and platform legacy settings, and record wishes. Executors: see the 30-day checklist and PDF.","/guides/what-to-do-when-someone-dies-digital-checklist/"),
("What happens to my Steam account when I die?","Steam games are licences that Valve says aren't transferable, including by operation of law.","/platforms/game-libraries/"),
("Google Inactive Account Manager vs Apple Legacy Contact?","Use both: Google acts after 3–18 months of inactivity; Apple needs an access key plus death certificate and gives 3 years of access.","/compare/google-inactive-account-manager-vs-apple-legacy-contact/")]
